def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return (float("inf"), None)
    
    # Initialize the distance dictionary and the parent dictionary for BFS
    distances = {node: float("inf") for node in graph}
    parent = {node: None for node in graph}
    distances[source] = 0
    
    # Breadth-First Search
    queue = [source]
    while queue:
        node = queue.pop(0)
        for neighbor, weight in graph[node]:
            distance_through_node = distances[node] + weight
            if distance_through_node < distances[neighbor]:
                distances[neighbor] = distance_through_node
                parent[neighbor] = node
                # Add neighbor to the queue, but only if it hasn't been processed yet
                if neighbor not in distances:
                    queue.append(neighbor)
    
    # If target is not reachable, return infinity and none
    if distances[target] == float("inf"):
        return (float("inf"), None)
    
    # Reconstruct the path
    path = []
    current = target
    while current is not None:
        path.append(current)
        current = parent[current]
    path.reverse()
    
    return (distances[target], path)

